using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using Ged.Core.Compiler;
using Ged.Core.IO.Rfl;
using Ged.Core.IO.Rfl.Sections;
using Ged.Core.Model;

namespace Ged.Core.Tests.Compiler;

/// <summary>
/// The Alpine RED reference builds (C2, <c>research/fixtures/alpine-ref/&lt;alpine id&gt;/build</c>, generated by
/// <c>tools/alpine-ref.ps1</c>: Alpine RED <c>-bake … -buildonly</c> with RepairBuildHoles on). Each level has the
/// compiled output <c>.rfl</c>, its log, and a manifest row with the eleven BuildRepair counters. Retail- and
/// community-derived, gitignored: every consumer skips when <see cref="Find"/> returns null.
/// </summary>
internal static class AlpineReference
{
    /// <summary>The counter names in the order Alpine's log prints them (<c>build_repair.cpp:1507-1519</c>).</summary>
    public static readonly string[] CounterNames =
    {
        "Holes after building rooms", "Portal planes unified", "Portal copies moved", "Split rooms joined",
        "Vertices welded", "Edges split", "Collapsed faces removed", "Portal strips removed", "Portal gaps filled",
        "Wall gaps filled", "Unplaced portal faces removed",
    };

    public sealed record Level(string Name, string RflPath, bool Stock, int[] Counters);

    public sealed record Set(string Id, string Directory, IReadOnlyList<Level> Levels)
    {
        public Level? Get(string name) => Levels.FirstOrDefault(l => string.Equals(l.Name, name, StringComparison.OrdinalIgnoreCase));
    }

    /// <param name="Stock">The source level's own compiled geometry (stock RED for the retail corpus), when present.</param>
    public sealed record Loaded(Geometry Reference, List<Brush> Brushes, List<RoomEffect> Effects, Geometry? Stock);

    private static readonly Lazy<Set?> Cached = new(Locate);

    /// <summary>The newest reference set on disk (by manifest), or null when none is present.</summary>
    public static Set? Find() => Cached.Value;

    private static Set? Locate()
    {
        if (TestPaths.ResearchFixtures is not { } fixtures)
        {
            return null;
        }

        string root = Path.Combine(fixtures, "alpine-ref");
        if (!System.IO.Directory.Exists(root))
        {
            return null;
        }

        foreach (string dir in System.IO.Directory.GetDirectories(root).OrderByDescending(System.IO.Directory.GetLastWriteTimeUtc))
        {
            string build = Path.Combine(dir, "build");
            string manifest = Path.Combine(build, "manifest.json");
            if (File.Exists(manifest))
            {
                return Parse(Path.GetFileName(dir), build, manifest);
            }
        }

        return null;
    }

    private static Set? Parse(string id, string build, string manifestPath)
    {
        using JsonDocument doc = JsonDocument.Parse(File.ReadAllText(manifestPath));
        JsonElement root = doc.RootElement;
        if (root.TryGetProperty("repairBuildHoles", out JsonElement rep) && rep.ValueKind == JsonValueKind.False)
        {
            return null; // the gates are defined against repair-on references only (spec §11.1 Q8)
        }

        var stock = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (Corpus.Directory is { } corpus)
        {
            foreach (string f in System.IO.Directory.GetFiles(corpus, "*.rfl"))
            {
                stock.Add(Path.GetFileName(f));
            }
        }

        var levels = new List<Level>();
        foreach (JsonElement l in root.GetProperty("levels").EnumerateArray())
        {
            string name = l.GetProperty("level").GetString()!;
            if (!l.TryGetProperty("ok", out JsonElement ok) || ok.ValueKind != JsonValueKind.True)
            {
                continue;
            }

            string rfl = Path.Combine(build, name);
            if (!File.Exists(rfl))
            {
                continue;
            }

            int[] counters = new int[CounterNames.Length];
            if (l.TryGetProperty("repairCounters", out JsonElement c) && c.ValueKind == JsonValueKind.Object)
            {
                for (int i = 0; i < CounterNames.Length; i++)
                {
                    counters[i] = c.TryGetProperty(CounterNames[i], out JsonElement v) && v.TryGetInt32(out int n) ? n : -1;
                }
            }

            levels.Add(new Level(name, rfl, stock.Contains(name), counters));
        }

        return new Set(id, build, levels);
    }

    /// <summary>
    /// Loads the reference geometry plus the brushes/effects Glacier compiles. For a stock-corpus level the
    /// brushes come from <c>research/example_rfls</c> (exactly what <see cref="HoleParityGateTests"/> compiles);
    /// for a community exemplar they come from the reference file itself (a build does not change brushes).
    /// Mover brushes are excluded as RED's static fold does.
    /// </summary>
    public static bool TryLoad(Level level, out Loaded? loaded)
    {
        loaded = null;
        if (!TryRead(level.RflPath, out Geometry? reference, out _, out _, out _) || reference is null)
        {
            return false;
        }

        string source = level.Stock && Corpus.Directory is { } corpus ? Path.Combine(corpus, level.Name) : level.RflPath;
        if (!TryRead(source, out Geometry? stock, out List<Brush>? brushes, out List<RoomEffect>? effects, out RflFile? rfl) || brushes is null || rfl is null)
        {
            return false;
        }

        loaded = new Loaded(
            reference,
            MoverBrushes.ExcludeMovers(brushes, MoverBrushes.CollectMoverUids(rfl)),
            effects ?? new List<RoomEffect>(),
            level.Stock ? stock : null);
        return true;
    }

    private static bool TryRead(string path, out Geometry? geometry, out List<Brush>? brushes, out List<RoomEffect>? effects, out RflFile? rfl)
    {
        geometry = null;
        brushes = null;
        effects = null;
        rfl = RflFile.Load(path);
        rfl.ParseAllKnownSections();
        foreach (RflSection s in rfl.Sections)
        {
            if (s.Content is GeometrySection gs)
            {
                geometry ??= gs.Geometry;
            }
            else if (s.Content is BrushesSection bs)
            {
                brushes ??= bs.Brushes.ToList();
            }
            else if (s.Content is RoomEffectsSection es)
            {
                effects ??= es.Effects.ToList();
            }
        }

        return geometry is not null && brushes is not null;
    }

    public static int MainRooms(Geometry g) => g.Rooms.Count(r => r.IsSubroom == 0);

    /// <summary>
    /// Holes as Alpine RED's own CheckForHoles counts them (<c>build_repair.cpp:581-637</c>, RED <c>0x0043c420</c>):
    /// per non-detail room, an edge of one of its faces is open unless another face of the same room references
    /// both ends; open edges sharing a vertex form one hole. Liquid faces are not edge sources (RED's liquid
    /// surface is double-sided and closes on itself; Glacier's is single-sided).
    /// </summary>
    public static int AlpineRuleHoles(Geometry g)
    {
        var refs = new Dictionary<int, List<int>>();
        for (int fi = 0; fi < g.Faces.Count; fi++)
        {
            foreach (FaceVertex v in g.Faces[fi].Vertices)
            {
                if (!refs.TryGetValue(v.Index, out List<int>? l))
                {
                    refs[v.Index] = l = new List<int>();
                }

                if (l.Count == 0 || l[^1] != fi)
                {
                    l.Add(fi);
                }
            }
        }

        bool Refs(int v, int face) => refs.TryGetValue(v, out List<int>? l) && l.Contains(face);
        int holes = 0;
        foreach (IGrouping<int, int> room in Enumerable.Range(0, g.Faces.Count).GroupBy(i => g.Faces[i].RoomIndex))
        {
            if (room.Key < 0 || room.Key >= g.Rooms.Count || g.Rooms[room.Key].IsSubroom != 0)
            {
                continue;
            }

            var parent = new Dictionary<int, int>();
            int Find(int x)
            {
                while (parent.TryGetValue(x, out int p) && p != x)
                {
                    x = p;
                }

                return x;
            }

            bool any = false;
            foreach (int fi in room)
            {
                Face f = g.Faces[fi];
                if (((FaceFlags)f.Flags & FaceFlags.LiquidSurface) != 0)
                {
                    continue;
                }

                for (int k = 0; k < f.Vertices.Count; k++)
                {
                    int a = f.Vertices[k].Index;
                    int b = f.Vertices[(k + 1) % f.Vertices.Count].Index;
                    bool closed = refs[a].Any(o => o != fi && g.Faces[o].RoomIndex == room.Key && Refs(b, o));
                    if (closed)
                    {
                        continue;
                    }

                    any = true;
                    parent.TryAdd(a, a);
                    parent.TryAdd(b, b);
                    int ra = Find(a), rb = Find(b);
                    if (ra != rb)
                    {
                        parent[rb] = ra;
                    }
                }
            }

            if (any)
            {
                holes += parent.Keys.Select(Find).Distinct().Count();
            }
        }

        return holes;
    }

    /// <summary>holes (HoleDetector) / Alpine-rule holes / main rooms / portals / faces.</summary>
    public static string Stats(Geometry g) =>
        $"{HoleDetector.Detect(g).Count}/{AlpineRuleHoles(g)}/{MainRooms(g)}/{g.Portals.Count}/{g.Faces.Count}";
}
